import{_ as a,a0 as l,w as i,s as r,ao as d,I as s,x as u,a1 as o,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Ubuntu参考手册14.04 LTS第二版正式发布 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu参考手册14.04 LTS第二版正式发布 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu参考手册14.04 LTS第二版正式发布 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu参考手册14.04 LTS第二版正式发布 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141230 Second Edition of Ubuntu Manual 14.04 LTS Is Ou","title":"Ubuntu参考手册14.04 LTS第二版正式发布","tag":"201412","desc":""},"relativePath":"201412/20141230 Second Edition of Ubuntu Manual 14.04 LTS Is Ou.md","filePath":"[post].md"}'),p={name:"201412/20141230 Second Edition of Ubuntu Manual 14.04 LTS Is Ou.md"};function b(T,t,f,m,S,L){const n=l("Link");return i(),r("div",null,[t[19]||(t[19]=d('<h1 id="ubuntu参考手册14-04-lts第二版正式发布" tabindex="-1">Ubuntu参考手册14.04 LTS第二版正式发布 <a class="header-anchor" href="#ubuntu参考手册14-04-lts第二版正式发布" aria-label="Permalink to “Ubuntu参考手册14.04 LTS第二版正式发布”">​</a></h1><blockquote><p>初学者可以在手册里获得很有用的信息</p></blockquote><h3 id="ubuntu参考手册团队表示第二版手册现在已经发布并且可以免费下载" tabindex="-1">Ubuntu参考手册团队表示第二版手册现在已经发布并且可以免费下载 <a class="header-anchor" href="#ubuntu参考手册团队表示第二版手册现在已经发布并且可以免费下载" aria-label="Permalink to “Ubuntu参考手册团队表示第二版手册现在已经发布并且可以免费下载”">​</a></h3><p><img src="http://i1-linux.softpedia-static.com/screenshots/Ubuntu-Manual_1.jpg" alt=""></p><p>Ubuntu手册按照惯例会对应相应的LTS发行版本，那么唯一合理的解释就是，现在发布的手册对应于6个月前发布的Ubuntu 14.04 LTS(Trusty Tahr)。与其他书籍一样，特别是大型书籍，手册内容总会出现各种错误或者也许已经和现状不匹配。不过不管怎样，电子书的修正和更新总要方便一些。</p><p>你也许会觉得奇怪，一个方便上手的免费操作系统竟然会有一个参考手册，或许一个社区就已经足够了。但是，总是有一些新用户连基本的操作都不懂，因此，有一本可以指明最基本的东西的手册拿在手里总是一个很好不过的事情。</p><h3 id="这是-ubuntu-14-04-lts入门-手册的第二个版本" tabindex="-1">这是“Ubuntu 14.04 LTS入门”手册的第二个版本 <a class="header-anchor" href="#这是-ubuntu-14-04-lts入门-手册的第二个版本" aria-label="Permalink to “这是“Ubuntu 14.04 LTS入门”手册的第二个版本”">​</a></h3><p>使用Ubuntu操作系统的用户会发现，它和之前用过的其他操作系统有很大的差异，例如Windows和Max OS X。这很正常，并且你也不是任何时候都可以在网上找到一个特定的功能或者组件的相关资源和信息。有一个可以说明Ubuntu 14.04 LTS基本特性的手册可以提供一些帮助。</p><p>“《Ubuntu 14.04 入门 E2》对于Ubuntu操作系统而言，是一个很全面的初学者指南手册。它采用的是开源许可协议，你可以自由下载、阅读、修改以及共享。这个手册可以帮助你熟悉如何处理日常的工作，例如上网、听音乐或者扫描文档等等。尤其值得一提的是，这个文档浅显易懂，适合各个层次的用户。”</p>',9)),s("p",null,[t[1]||(t[1]=u("“这个快速入门手册可以让你很容易的利用你的计算机做一些事情，而不会陷入技术细节当中。在手册的帮助下，新用户可以很快的熟悉Unity桌面，”更多信息参考",-1)),o(n,{href:"http://ubuntu-manual.org/"},{default:e(()=>[...t[0]||(t[0]=[u("官方网站",-1)])]),_:1}),t[2]||(t[2]=u("。",-1))]),s("p",null,[t[4]||(t[4]=u("这是该参考手册的第二版，制作手册的团队具有丰富的经验。就算你已经是一个Ubuntu用户，看一看这个手册也没有什么坏处，因为你总能从其中学到一些东西。你可以在Softpedia",-1)),o(n,{href:"http://linux.softpedia.com/get/Documentation/Ubuntu-Manual-53530.shtml"},{default:e(()=>[...t[3]||(t[3]=[u("下载Ubuntuy参考手册14.04第二版",-1)])]),_:1}),t[5]||(t[5]=u("。",-1))]),t[20]||(t[20]=s("hr",null,null,-1)),s("p",null,[t[7]||(t[7]=u("via: ",-1)),o(n,{href:"http://news.softpedia.com/news/Second-Edition-of-Ubuntu-Manual-14-04-LTS-Is-Out-468395.shtml"},{default:e(()=>[...t[6]||(t[6]=[u("http://news.softpedia.com/news/Second-Edition-of-Ubuntu-Manual-14-04-LTS-Is-Out-468395.shtml",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=u("作者：",-1)),o(n,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:e(()=>[...t[8]||(t[8]=[u("Silviu Stahie",-1)])]),_:1}),t[12]||(t[12]=u(" 译者：",-1)),o(n,{href:"https://github.com/zhouj-sh"},{default:e(()=>[...t[9]||(t[9]=[u("zhouj-sh",-1)])]),_:1}),t[13]||(t[13]=u(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[10]||(t[10]=[u("wxy",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=u("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[14]||(t[14]=[u("LCTT",-1)])]),_:1}),t[17]||(t[17]=u(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:e(()=>[...t[15]||(t[15]=[u("Linux中国",-1)])]),_:1}),t[18]||(t[18]=u(" 荣誉推出",-1))])])}const M=a(p,[["render",b]]);export{C as __pageData,M as default};
